<?php $h = static fn($v) => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); ?>
<div class="container-fluid py-3">
  <div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3 mb-0">Étiquettes</h1><div class="btn-group"><a class="btn btn-outline-secondary" href="<?= url('/notes') ?>">Notes</a><a class="btn btn-primary" href="<?= url('/labels/create') ?>">Nouvelle étiquette</a></div></div>
  <form method="get" class="card card-body mb-3"><div class="row g-2"><div class="col-md-6"><input class="form-control" name="q" placeholder="Recherche" value="<?= $h($filters['q'] ?? '') ?>"></div><div class="col-md-4"><select name="societe_id" class="form-select"><option value="0">Toutes sociétés</option><?php foreach (($refs['societes'] ?? []) as $s): ?><option value="<?= (int)$s['soc_id'] ?>" <?= (int)($filters['societe_id'] ?? 0)===(int)$s['soc_id']?'selected':'' ?>><?= $h($s['soc_nom']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filtrer</button></div></div></form>
  <div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>ID</th><th>Code</th><th>Libellé</th><th>Société</th><th>Couleur</th><th>Affectations</th><th></th></tr></thead><tbody><?php foreach ($etiquettes as $e): ?><tr><td><?= (int)$e['eti_id'] ?></td><td><code><?= $h($e['eti_code']) ?></code></td><td><?= $h($e['eti_libelle']) ?></td><td><?= $h($e['societe_nom'] ?? 'Globale') ?></td><td><?= $h($e['eti_couleur'] ?? '') ?></td><td><?= (int)($e['affectations_count'] ?? 0) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="<?= url('/labels/' . (int)$e['eti_id'] . '/edit') ?>">Modifier</a></td></tr><?php endforeach; ?><?php if (!$etiquettes): ?><tr><td colspan="7" class="text-center text-muted py-4">Aucune étiquette.</td></tr><?php endif; ?></tbody></table></div></div>
